package dao; import model.User;import util.*;import java.sql.*;import java.util.*; /** DAO JDBC com PreparedStatement. */ public class UserDAO{public User find(String id)throws SQLException{return q("SELECT * FROM users WHERE id=?",id);}public User byEmail(String e)throws SQLException{return q("SELECT * FROM users WHERE lower(email)=lower(?)",e);}private User q(String sql,String v)throws SQLException{try(Connection c=Database.open();PreparedStatement p=c.prepareStatement(sql)){p.setString(1,v);try(ResultSet r=p.executeQuery()){return r.next()?read(r):null;}}}public User create(String n,String e,String h,String t)throws SQLException{String id=UUID.randomUUID().toString();try(Connection c=Database.open();PreparedStatement p=c.prepareStatement("INSERT INTO users(id,nome,email,senha_hash,telefone) VALUES(?,?,?,?,?)")){p.setString(1,id);p.setString(2,n);p.setString(3,e);p.setString(4,h);p.setString(5,t);p.executeUpdate();}return find(id);}public void update(User u)throws SQLException{try(Connection c=Database.open();PreparedStatement p=c.prepareStatement("UPDATE users SET nome=?,telefone=?,avatar_url=?,tipo_sanguineo=?,alergias=?,medicamentos_em_uso=?,plano_de_saude=?,contato_emergencia_nome=?,contato_emergencia_telefone=?,contato_emergencia_parentesco=? WHERE id=?")){int i=1;p.setString(i++,u.nome);p.setString(i++,u.telefone);p.setString(i++,u.avatarUrl);p.setString(i++,u.tipoSanguineo);p.setString(i++,u.alergias);p.setString(i++,u.medicamentosEmUso);p.setString(i++,u.planoDeSaude);p.setString(i++,u.contatoEmergenciaNome);p.setString(i++,u.contatoEmergenciaTelefone);p.setString(i++,u.contatoEmergenciaParentesco);p.setString(i,u.id);p.executeUpdate();}}public static User read(ResultSet r)throws SQLException{User u=new User();u.id=r.getString("id");u.nome=r.getString("nome");u.email=r.getString("email");u.telefone=r.getString("telefone");u.avatarUrl=r.getString("avatar_url");u.tipoSanguineo=r.getString("tipo_sanguineo");u.alergias=r.getString("alergias");u.medicamentosEmUso=r.getString("medicamentos_em_uso");u.planoDeSaude=r.getString("plano_de_saude");u.emailVerificado=r.getBoolean("email_verificado");u.senhaHash=r.getString("senha_hash");return u;}}
